'DECLARE',
'  l_http_req   UTL_HTTP.req;',
'  l_http_resp  UTL_HTTP.resp;',
'  l_raw        RAW(32767);',
'  l_blob       BLOB;',
'  l_dest_offset INTEGER := 1;',
'  l_src_offset  INTEGER := 1;',
'BEGIN',
'  -- Crear BLOB temporal',
'  DBMS_LOB.createtemporary(l_blob, TRUE);',
'',
'  -- Solicitud HTTP',
'  l_http_req := UTL_HTTP.begin_request(',
'    ''http://129.213.192.254:8080/jasperserver/rest_v2/reports/themes/Reports/Consentimiento_v6.2.pdf?IDPOLIZA=''||:P2_IDPOLIZA,',
'    ''GET'',',
'    ''HTTP/1.1''',
'  );',
'  UTL_HTTP.set_authentication(l_http_req, ''jasperadmin'', ''jasperadmin'');',
'  l_http_resp := UTL_HTTP.get_response(l_http_req);',
'',
'  -- Leer respuesta en RAW y escribirla en BLOB',
'  BEGIN',
'    LOOP',
'      UTL_HTTP.read_raw(l_http_resp, l_raw, 32767);',
'      DBMS_LOB.writeappend(l_blob, UTL_RAW.length(l_raw), l_raw);',
'    END LOOP;',
'  EXCEPTION',
'    WHEN UTL_HTTP.end_of_body THEN',
'      NULL;',
'  END;',
'',
'  -- Cabeceras HTTP',
'  owa_util.mime_header(''application/pdf'', FALSE);',
'  htp.p(''Content-Disposition: attachment; filename="Reporte_Param.pdf"'');',
'  owa_util.http_header_close;',
'',
'  -- Enviar el BLOB correctamente',
'  wpg_docload.download_file(l_blob);',
'',
'  -- Cerrar respuesta HTTP',
'  UTL_HTTP.end_response(l_http_resp);',
'  apex_application.stop_apex_engine;',
'END;',
''))
,p_process_clob_language=>'PLSQL'
,p_internal_uid=>33076668980030249
);
end;
